/// One role of a type scale.
final class TypeRole {
  const TypeRole({
    required this.size,
    required this.lineHeight,
    required this.weight,
  });

  final double size;
  final double lineHeight;
  final int weight;
}

/// The type scale of one surface.
final class TypeScale {
  const TypeScale({
    required this.caption,
    required this.secondary,
    required this.body,
    required this.subtitle,
    required this.title,
    required this.largeTitle,
    required this.number,
  });

  final TypeRole caption;
  final TypeRole secondary;
  final TypeRole body;
  final TypeRole subtitle;
  final TypeRole title;
  final TypeRole largeTitle;
  final TypeRole number;
}

